#include <algorithm>
#include <array>
#include <cstdlib>
#include <iostream>
#include <set>
#include <stdexcept>
#include <vector>

using Form = std::array<int, 4>;
using Grid = std::array<int, 9>;
using Readout = std::array<int, 10>;

const std::array<Form, 9> CELL_FORMS = {
    Form{1,0,0,0}, Form{0,1,0,0}, Form{-1,-1,0,0},
    Form{0,0,1,0}, Form{0,0,0,1}, Form{0,0,-1,-1},
    Form{-1,0,-1,0}, Form{0,-1,0,-1}, Form{1,1,1,1}
};

void add(Form& out, const Form& value) {
    for (int i = 0; i < 4; ++i) out[i] += value[i];
}

int minor3(const Form& a, const Form& b, const Form& c, int i, int j, int k) {
    return a[i]*(b[j]*c[k]-b[k]*c[j]) - a[j]*(b[i]*c[k]-b[k]*c[i])
           + a[k]*(b[i]*c[j]-b[j]*c[i]);
}

int determinant(const Form& a, const Form& b, const Form& c, const Form& d) {
    return a[0]*minor3(b,c,d,1,2,3) - a[1]*minor3(b,c,d,0,2,3)
           + a[2]*minor3(b,c,d,0,1,3) - a[3]*minor3(b,c,d,0,1,2);
}

struct Counts {
    int types = 0;
    long long bases = 0;
    long long determinant_two = 0;
    int max_determinant = 0;
    long long tested_midpoints = 0;
    long long strict_midpoints = 0;
};

void check_bases(const Grid& order, const Grid& wrap, Counts& seen) {
    Form carry{}, prefix{};
    for (int i = 0; i < 9; ++i) if (wrap[i]) add(carry, CELL_FORMS[i]);
    std::set<Form> forms(CELL_FORMS.begin(), CELL_FORMS.end());
    for (int i : order) {
        add(prefix, CELL_FORMS[i]);
        forms.insert(prefix);
    }
    forms.erase(Form{});
    forms.erase(carry);
    std::vector<Form> rows(forms.begin(), forms.end());
    const bool requires_carry = carry != Form{};
    if (requires_carry) rows.insert(rows.begin(), carry);

    int size = static_cast<int>(rows.size());
    for (int i = 0; i < (requires_carry ? 1 : size); ++i)
      for (int j = i + 1; j < size; ++j)
        for (int k = j + 1; k < size; ++k)
          for (int l = k + 1; l < size; ++l) {
              int d = std::abs(determinant(rows[i], rows[j], rows[k], rows[l]));
              ++seen.bases;
              seen.max_determinant = std::max(seen.max_determinant, d);
              if (d == 2) ++seen.determinant_two;
              if (d > 2) throw std::runtime_error("basis determinant exceeds two");
          }
}

std::vector<int> support(int mask) {
    std::vector<int> indices;
    for (int i = 0; i < 3; ++i) if ((mask >> i) & 1) indices.push_back(i);
    return indices;
}

Readout readout(const Grid& table, const Grid& order, const Grid& wrap) {
    Readout result{};
    for (int i = 0; i < 9; ++i) result[0] += table[i] * wrap[i];
    int prefix = 0;
    for (int i = 0; i < 9; ++i) {
        prefix += table[order[i]];
        result[i+1] = prefix;
    }
    return result;
}

void check_midpoints(const Grid& order, const Grid& wrap, Counts& seen) {
    // Every fractional-part table is half of two matchings on common supports.
    for (int row_mask = 1; row_mask < 8; ++row_mask) {
        auto rows = support(row_mask);
        for (int col_mask = 1; col_mask < 8; ++col_mask) {
            auto cols = support(col_mask);
            if (cols.size() != rows.size() || cols.size() < 2) continue;
            std::vector<Readout> options;
            do {
                Grid table{};
                for (std::size_t i = 0; i < rows.size(); ++i) {
                    table[3*rows[i] + cols[i]] = 1;
                }
                options.push_back(readout(table, order, wrap));
            } while (std::next_permutation(cols.begin(), cols.end()));
            for (std::size_t i = 0; i < options.size(); ++i)
              for (std::size_t j = i + 1; j < options.size(); ++j) {
                  Readout sum{};
                  for (int k = 0; k < 10; ++k) sum[k] = options[i][k] + options[j][k];
                  if (sum[0] % 2) continue;
                  ++seen.tested_midpoints;
                  bool strict = false;
                  for (int k = 0; k < 10; ++k)
                      if (sum[k] % 2 == 0 && options[i][k] != options[j][k]) strict = true;
                  if (strict) ++seen.strict_midpoints;
                  auto matches = [&sum](const Readout& candidate) {
                      for (int k = 0; k < 10; ++k) {
                          if (sum[k] % 2 == 0 && 2 * candidate[k] != sum[k]) return false;
                      }
                      return true;
                  };
                  if (std::none_of(options.begin(), options.end(), matches))
                      throw std::runtime_error("midpoint with no integer matching");
              }
        }
    }
}

void check_single_forbidden_cell() {
    Grid order{0,5,7,3,8,1,6,2,4};
    Grid wrap{0,0,0,0,0,1,0,1,1};
    auto perm = [](const std::array<int,3>& cols) {
        Grid table{};
        for (int i = 0; i < 3; ++i) table[3*i + cols[i]] = 1;
        return table;
    };
    auto a = readout(perm({2,1,0}),order,wrap);
    auto b = readout(perm({0,2,1}),order,wrap);
    // Columns 2 and 7 of the readout are prefixes at h=2 and h=9.
    if (a[0]+b[0] != 2 || a[2]+b[2] != 2 || a[7]+b[7] != 4)
        throw std::runtime_error("bad fractional witness");
    std::array<int,3> cols{0,1,2};
    int integer_solutions = 0;
    do {
        auto table = perm(cols);
        auto v = readout(table,order,wrap);
        if (v[0] == 1 && v[2] == 1 && v[7] == 2) {
            if (!table[8]) throw std::runtime_error("forbidden cell example admits a solution");
            ++integer_solutions;
        }
    } while (std::next_permutation(cols.begin(),cols.end()));
    if (integer_solutions != 1) throw std::runtime_error("expected exactly one dense integer solution");
}

int main() {
    Grid order{}, wrap{};
    Counts seen;
    while (std::cin >> order[0]) {
        for (int i = 1; i < 9; ++i) if (!(std::cin >> order[i])) return 1;
        for (int& i : wrap) if (!(std::cin >> i)) return 1;
        std::set<int> indices(order.begin(), order.end());
        if (indices.size() != 9 || *indices.begin() != 0 || *indices.rbegin() != 8 ||
            std::any_of(wrap.begin(), wrap.end(), [](int x) { return x < 0 || x > 1; }))
            return 1;
        ++seen.types;
        check_bases(order, wrap, seen);
        check_midpoints(order, wrap, seen);
    }
    if (!std::cin.eof() || !seen.types) return 1;
    check_single_forbidden_cell();
    std::cout << "types=" << seen.types << " bases=" << seen.bases
              << " determinant_two=" << seen.determinant_two
              << " max_determinant=" << seen.max_determinant
              << " integral_carry_midpoints=" << seen.tested_midpoints
              << " nontrivial_integral_observations=" << seen.strict_midpoints
              << " holes=0 single_forbidden_cell_hole=verified\n";
}

