"""Bounded 3-by-4 search for midpoint holes with one prefix and unit columns."""
from itertools import combinations, product
from math import gcd


def order_types(limit=10):
    seen = set()
    for m in range(3, limit + 1):
        for n in range(4, limit + 1):
            if gcd(m, n) != 1:
                continue
            for rows in combinations(range(m), 3):
                for columns in combinations(range(n), 4):
                    modulus = m * n
                    lifts = [n*i + m*j for i in rows for j in columns]
                    carry = tuple(x // modulus for x in lifts)
                    residues = [x % modulus for x in lifts]
                    order = tuple(sorted(range(12), key=residues.__getitem__))
                    if (order, carry) not in seen:
                        seen.add((order, carry))
                        yield m, n, rows, columns, order, carry, residues


def probe():
    count = 0
    for m, n, rows, columns, order, carry, residues in order_types():
        count += 1
        by_margin = {}
        for projection in product(range(3), repeat=4):
            margin = tuple(projection.count(i) for i in range(3))
            if 0 in margin:
                continue
            cells = {4*i+j for j,i in enumerate(projection)}
            e = sum(carry[i] for i in cells)
            prefixes = []
            total = 0
            for i in order:
                total += i in cells
                prefixes.append(total)
            by_margin.setdefault(margin, []).append((projection, e, prefixes))
        for margin, tables in by_margin.items():
            for h in range(11):
                observed = {(e, p[h]) for _, e, p in tables}
                for (left,e,p), (right,f,q) in combinations(tables, 2):
                    if (e+f)%2 or (p[h]+q[h])%2:
                        continue
                    target = ((e+f)//2, (p[h]+q[h])//2)
                    if target not in observed:
                        return (m,n,rows,columns,margin,residues[order[h]]+1,
                                target,left,right,sorted(observed))
    return {"order_carry_types": count, "midpoint_holes": 0}


if __name__ == "__main__":
    print(probe())

"""Replay the EC49GBO residual-matroid rank and deletion-cost formulas."""

from collections import Counter
from functools import cache
from itertools import combinations_with_replacement, product
import json
from random import Random


def subsets(mask):
    current = mask
    while current:
        yield current
        current = (current - 1) & mask
    yield 0


def ports(mask):
    while mask:
        port = mask & -mask
        yield port
        mask ^= port


def capacity(caps, mask):
    return sum(caps[port.bit_length() - 1] for port in ports(mask))


def inside(edges, cut):
    return sum(edge & ~cut == 0 for edge in edges)


@cache
def all_matched(caps, edges):
    slots = tuple(1 << i for i, cap in enumerate(caps) for _ in range(cap))
    reachable = {0}
    for edge in edges:
        reachable = {
            used | (1 << i) for used in reachable for i, slot in enumerate(slots)
            if edge & slot and used & (1 << i) == 0
        }
        if not reachable:
            return False
    return True


def independent(caps, ground, edges):
    for port in ports(ground):
        if capacity(caps, port) == 0:
            return False
        reduced = tuple(cap - (1 << i == port) for i, cap in enumerate(caps))
        if not all_matched(reduced, tuple(sorted(edges))):
            return False
    return True


def greedy(caps, ground, fixed, eligible):
    selected = list(fixed)
    if not independent(caps, ground, selected):
        return None
    deleted = 0
    for mask, weight in sorted(eligible, key=lambda item: item[1], reverse=True):
        selected.append(mask)
        if not independent(caps, ground, selected):
            selected.pop()
            deleted += weight
    return deleted


def brute(caps, ground, fixed, eligible):
    cuts = [cut for cut in subsets(ground) if cut]
    best = None
    for deletion in range(1 << len(eligible)):
        kept = list(fixed)
        cost = 0
        for index, (mask, weight) in enumerate(eligible):
            if deletion & (1 << index):
                cost += weight
            else:
                kept.append(mask)
        if all(inside(kept, cut) < capacity(caps, cut) for cut in cuts):
            best = cost if best is None else min(best, cost)
    return best


def packed_defect(caps, ground, edges):
    @cache
    def solve(available):
        if not available:
            return 0
        first = available & -available
        best = solve(available ^ first)
        for cut in subsets(available):
            if cut & first:
                defect = inside(edges, cut) - capacity(caps, cut) + 1
                best = max(best, defect + solve(available ^ cut))
        return best

    return solve(ground)


def check(caps, labels, eligible_labels, counts):
    full = (1 << len(caps)) - 1
    for ground in subsets(full):
        fixed = []
        eligible = []
        for index, mask in enumerate(labels):
            residual = mask & ground
            if residual:
                if eligible_labels & (1 << index):
                    eligible.append((residual, (3 * mask + 5 * index) % 7))
                else:
                    fixed.append(residual)
        units = [(mask, 1) for mask, _ in eligible]
        unit_cost = greedy(caps, ground, fixed, units)
        assert unit_cost == brute(caps, ground, fixed, units)
        assert greedy(caps, ground, fixed, eligible) == brute(caps, ground, fixed, eligible)
        counts["unit_thresholds"] += 1
        counts["weighted_thresholds"] += 1
        if unit_cost is not None:
            all_edges = fixed + [mask for mask, _ in eligible]
            assert unit_cost == packed_defect(caps, ground, all_edges)
            counts["disjoint_block_certificates"] += 1
        else:
            counts["infeasible_thresholds"] += 1


def main():
    counts = Counter()
    for caps in product(range(3), repeat=2):
        for length in range(5):
            for labels in combinations_with_replacement(range(4), length):
                for pool in range(1 << length):
                    check(caps, labels, pool, counts)
                    counts["exhaustive_instances"] += 1
    rng = Random(4926112702)
    for _ in range(400):
        width = rng.randint(3, 4)
        caps = tuple(rng.randrange(3) for _ in range(width))
        labels = tuple(rng.randrange(1 << width) for _ in range(rng.randrange(9)))
        check(caps, labels, rng.randrange(1 << len(labels)), counts)
        counts["seeded_instances"] += 1
    assert greedy((1, 1), 3, [], [(1, 1), (2, 1)]) == 2
    assert greedy((2,), 1, [1], [(1, 3)]) == 3
    assert greedy((2,), 1, [1], [(1, 1)]) == 1
    print(json.dumps(counts, indent=2, sort_keys=True))


if __name__ == "__main__":
    main()

