// All rays are nonnegative and represent points with u+v+w=1.
function clip(poly, row) {
  const values=poly.map(v => dot(v,row));
  if (values.every(v => v>=0n)) return poly;
  const out=[];
  for (let j=0;j<poly.length;j++) {
